-- WBS templates by building type (Master Libraries > WBS Templates).
--
-- A WBS template follows a construction pattern, not a whole sector: villas and towers are built
-- differently, so one template per sector would not fit, and one per building type would be 33
-- near-copies. Each template carries its sector (template_category = projects.category slug) and the
-- building types it fits (building_types = projects.building_type slugs, lib/project-categories.ts);
-- pickers recommend the templates matching a project's building type. Empty building_types = fits
-- any project in its sector.
--
-- Seeds 14 templates (Design, Procurement, Construction, Commissioning & Handover sections plus
-- basement / ground / typical / roof floor blocks). Activities inside a group are linked
-- finish-to-start; each floor block's first structural activity follows the slab pour (key 01.09) of
-- the floor below. No dates, no ids from any project. Skipped where a template of the same name
-- exists, so local edits are kept.

alter table public.wbs_templates
  add column if not exists building_types text[] not null default '{}';

comment on column public.wbs_templates.template_category is
  'Sector slug (projects.category), e.g. residential; free text allowed for company-specific groups.';
comment on column public.wbs_templates.building_types is
  'Building-type slugs (projects.building_type) this template is recommended for; empty = any in its sector.';

-- Sector labels saved before this migration become slugs.
update public.wbs_templates
   set template_category = case lower(btrim(template_category))
         when 'mixed-use' then 'commercial'
         when 'mixed use' then 'commercial'
         else lower(btrim(template_category)) end
 where lower(btrim(template_category)) in
       ('residential', 'commercial', 'industrial', 'institutional', 'infrastructure', 'mixed-use', 'mixed use');

update public.wbs_templates
   set building_types = array['mixed_use_building']
 where template_name = '7F Mixed-use (from PRJ-2026-004-PC)' and building_types = '{}';

create or replace function public.save_wbs_template(p jsonb)
 returns uuid
 language plpgsql
 set search_path to 'public'
as $function$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_types text[] := case when jsonb_typeof(p->'building_types') = 'array'
                         then array(select jsonb_array_elements_text(p->'building_types')) end;
begin
  if coalesce(btrim(p->>'template_name'), '') = '' then
    raise exception 'Template name is required' using errcode = '22023';
  end if;
  if jsonb_typeof(p->'content') is distinct from 'object' then
    raise exception 'Template content is required' using errcode = '22023';
  end if;
  if v_id is null then
    insert into public.wbs_templates
      (template_name, template_desc, template_category, building_types, is_active, source,
       default_level_template_id, content, version, created_by)
    values
      (btrim(p->>'template_name'), nullif(p->>'template_desc', ''), nullif(p->>'template_category', ''),
       coalesce(v_types, '{}'), coalesce((p->>'is_active')::boolean, true), nullif(p->>'source', ''),
       nullif(p->>'default_level_template_id', '')::uuid, p->'content', 1, auth.uid())
    returning id into v_id;
  else
    update public.wbs_templates
       set template_name             = btrim(p->>'template_name'),
           template_desc             = nullif(p->>'template_desc', ''),
           template_category         = nullif(p->>'template_category', ''),
           building_types            = coalesce(v_types, building_types),
           is_active                 = coalesce((p->>'is_active')::boolean, is_active),
           source                    = coalesce(nullif(p->>'source', ''), source),
           default_level_template_id = nullif(p->>'default_level_template_id', '')::uuid,
           content                   = p->'content',
           version                   = version + 1,
           updated_at                = now()
     where id = v_id;
    if not found then
      raise exception 'Template not found or not permitted' using errcode = '42501';
    end if;
  end if;
  return v_id;
end $function$;

